  f.db.sql("CREATE TRIGGER no_reader_book_update BEFORE UPDATE ON bookings BEGIN SELECT RAISE(FAIL,'readonly'); END;CREATE TRIGGER no_reader_meta_update BEFORE UPDATE ON booking_metadata BEGIN SELECT RAISE(FAIL,'readonly'); END;CREATE TRIGGER no_reader_dispatch_update BEFORE UPDATE ON dispatch_requests BEGIN SELECT RAISE(FAIL,'readonly'); END;");const auto guarded=f.db.dump();present(f.read());check(f.db.dump()==guarded,"exact replay does no UPDATE even with failing write triggers");{BookingStore reopened(f.file);const auto again=reopened.savedInitialStartAdmission(Request,Device.toLower(),Observation,std::nullopt);present(again);check(again.receiptUtf8==receipt&&again.admission.dispatch->bookingId==f.booking,"reopen/current device normalization retain exact native receipt");}check(f.db.dump()==guarded,"reopen reader preserves all immutable records");
